<template>
 <main v-if="active" class="delivery-author">
  <section v-for="screen in screens" :key="screen.key">
   <header class="heading"><div><h2>配送员目录</h2><p>选择商城用户，管理配送员头像、姓名、手机号和状态。</p></div><div class="actions"><el-button :disabled="state.busy" @click="screen.refresh">重新读取配送员</el-button><el-button v-if="canManage" type="primary" :disabled="!model.writable() || !!state.editor || !state.snapshot?.can_create" @click="screen.create">新增配送员</el-button></div></header>
   <el-alert v-if="state.pending" title="原配送员操作结果尚未确认，新的提交已暂停" type="warning" :closable="false"><p>未找到回执仍表示结果未知。请读取回执，或主动核对并封存原请求。</p><div class="actions"><el-button :disabled="state.busy" @click="screen.receipt">读取原回执</el-button><el-button :disabled="state.busy" @click="screen.resolve">核对并封存原请求</el-button><el-button v-if="state.retryReady && canManage" :disabled="state.busy" @click="screen.retry">原样重试</el-button></div></el-alert>
   <el-alert v-if="!canView" title="当前没有配送员查看权限" type="warning" :closable="false" /><el-alert v-if="state.error || state.pendingError" :title="state.error || state.pendingError" type="error" :closable="false" /><el-alert v-if="state.notice" :title="state.notice" type="success" :closable="false" />
   <template v-if="canView"><el-alert v-if="state.snapshot && !state.snapshot.can_create" title="历史配送员记录已达容量上限，暂不能新增" type="warning" :closable="false" /><el-alert v-if="state.snapshot && !state.snapshot.write_ready" title="此环境尚未安装配送员安全写入能力，目录可查看" type="warning" :closable="false" />
    <div class="filters"><label>姓名、电话或UID<input aria-label="配送员关键词" :value="state.filters.keyword" :disabled="model.viewLocked()" @input="screen.keyword(($event.target as HTMLInputElement).value)" /></label><el-button :disabled="model.viewLocked()" @click="screen.reset">重置查询</el-button></div>
    <p class="hint">共 {{ state.snapshot?.count ?? 0 }} 项，当前范围 {{ visible.length }} 项，每页20项。仅管理平台配送员，关联用户在创建后固定。</p><p v-if="state.loading" role="status">正在读取配送员目录…</p>
    <div v-if="state.snapshot && !state.loading" aria-label="配送员列表" class="delivery-rows"><article v-for="item in rows" :key="item.key" class="delivery-row"><div class="delivery-info"><div class="identity"><img v-if="deliveryPreview(item.row.avatar_preview)" :src="deliveryPreview(item.row.avatar_preview)" alt="配送员头像" class="delivery-thumbnail" /><div><strong>{{ item.row.nickname || '未命名历史配送员' }}</strong><p>#{{ item.row.id }} · UID {{ item.row.uid }} · {{ item.row.user_nickname || '历史用户' }}</p></div></div><p>{{ item.row.phone }}</p><p>状态：{{ item.row.status === 1 ? '启用' : item.row.status === 0 ? '停用' : `历史值 ${item.row.status}` }}</p></div><div v-if="canManage" class="actions"><el-button :disabled="!model.writable() || !!state.editor" @click="item.edit">编辑配送员</el-button><el-button :disabled="!model.writable() || !!state.editor" @click="item.status">{{ item.row.status === 1 ? '停用配送员' : '启用配送员' }}</el-button><el-button type="danger" plain :disabled="!model.writable() || !!state.editor" @click="item.remove">删除配送员</el-button></div></article><p v-if="!visible.length" class="hint empty">没有符合条件的配送员</p></div>
    <nav class="actions pagination" aria-label="配送员分页"><span>第 {{ state.filters.page }} / {{ pageCount }} 页</span><el-button :disabled="model.viewLocked() || state.filters.page <= 1" @click="screen.previous">上一页配送员</el-button><el-button :disabled="model.viewLocked() || state.filters.page >= pageCount" @click="screen.next">下一页配送员</el-button></nav>
   </template>
  </section>
  <el-dialog v-for="editor in editors" :key="editor.key" class="delivery-author-dialog" top="16px" :model-value="true" :title="state.editor?.row ? '编辑配送员' : '新增配送员'" width="min(720px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false" :destroy-on-close="true">
   <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" /><div class="editor-fields">
    <fieldset><legend>关联商城用户</legend><p aria-label="已选用户">UID {{ editor.user.uid }} · {{ editor.user.name || '尚未选择或历史用户' }}</p><el-button v-if="!editor.user.immutable" :disabled="editorLocked" @click="editor.user.open">选择商城用户</el-button><small>{{ editor.user.immutable ? '编辑时关联用户固定。' : '姓名或手机号留空时使用所选用户资料；可另选头像。' }}</small></fieldset>
    <label v-for="field in editor.fields" :key="field.key">{{ labels[field.field] }}<select v-if="field.field === 'status'" :aria-label="labels[field.field]" :value="field.value" :disabled="editorLocked" @change="field.set(Number(($event.target as HTMLSelectElement).value))"><option :value="0">关闭</option><option :value="1">开启</option><option v-if="![0,1].includes(Number(field.value))" :value="field.value">保留历史值 {{ field.value }}</option></select><input v-else :value="field.value" :aria-label="labels[field.field]" :disabled="editorLocked" @input="field.set(($event.target as HTMLInputElement).value)" /></label>
    <fieldset v-for="image in editor.images" :key="image.key"><legend>配送员头像</legend><img v-if="image.preview" :key="image.nativeKey" class="editor-avatar" :src="image.preview" alt="配送员头像预览" @error="image.error" /><p v-else class="hint">原头像暂不可预览，可保留原值或另选头像。</p><label>头像稳定地址<input aria-label="配送员头像地址" :value="image.reference" :disabled="editorLocked" @input="image.set(($event.target as HTMLInputElement).value)" /></label><small>支持HTTPS或站内稳定图片地址；预览票据不会写入资料。</small><el-button :disabled="editorLocked" @click="image.open">选择头像图片</el-button></fieldset>
   </div><template #footer><el-button :disabled="editorLocked" @click="editor.cancel">取消编辑配送员</el-button><el-button type="primary" :disabled="editorLocked" @click="editor.submit">核对配送员保存</el-button></template>
  </el-dialog>
  <el-dialog v-for="picker in userPickers" :key="picker.key" class="delivery-author-dialog" top="16px" :model-value="true" title="选择商城用户" width="min(820px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="picker.error" :title="picker.error" type="error" :closable="false" /><div class="picker-filters"><label>用户UID或昵称<input aria-label="商城用户关键词" :value="picker.keyword" @input="picker.keywordChange(($event.target as HTMLInputElement).value)" /></label><el-button @click="picker.search">查询商城用户</el-button></div><p v-if="picker.loading" role="status">正在读取真实用户…</p><div class="user-options"><button v-for="item in picker.items" :key="item.key" type="button" class="delivery-user-option" :aria-label="`选择用户 ${item.uid}`" :disabled="picker.loading" @click="item.choose"><img v-if="deliveryPreview(item.preview)" :src="deliveryPreview(item.preview)" alt="用户头像" /><span>{{ item.nickname || '未设置昵称' }} · UID {{ item.uid }}</span></button><p v-if="!picker.loading && !picker.items.length">没有符合条件的有效用户</p></div><template #footer><div class="actions"><span>共 {{ picker.count }} 项 · 第 {{ picker.page }} 页</span><el-button :disabled="picker.loading || picker.page <= 1" @click="picker.previous">上一页商城用户</el-button><el-button :disabled="picker.loading || picker.page * 20 >= picker.count" @click="picker.next">下一页商城用户</el-button><el-button @click="picker.close">返回配送员编辑</el-button></div></template></el-dialog>
  <el-dialog v-for="picker in pickers" :key="picker.key" class="delivery-author-dialog" top="16px" :model-value="true" title="选择头像图片" width="min(820px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="picker.error" :title="picker.error" type="error" :closable="false" /><div class="picker-filters"><label>图片分类<select aria-label="头像图片分类" :value="picker.pid" @change="picker.category(Number(($event.target as HTMLSelectElement).value))"><option :value="0">未分类</option><option v-for="category in picker.categories" :key="category.id" :value="category.id">{{ category.name }} #{{ category.id }}</option></select></label><label>图片名称<input :value="picker.name" aria-label="头像图片名称" @input="picker.nameChange(($event.target as HTMLInputElement).value)" /></label><el-button @click="picker.search">查询头像图片</el-button></div><p v-if="picker.loading" role="status">正在读取图片…</p><div class="image-options"><button v-for="item in picker.items" :key="item.key" type="button" class="delivery-image-option" :aria-label="`选择图片 ${item.real_name}`" :disabled="picker.loading" @click="item.choose"><img :src="item.preview" :alt="item.real_name" /><span>{{ item.real_name }}</span></button><p v-if="!picker.loading && !picker.items.length">没有可选图片</p></div><template #footer><div class="actions"><span>共 {{ picker.count }} 项 · 第 {{ picker.page }} 页</span><el-button :disabled="picker.loading || picker.page <= 1" @click="picker.previous">上一页头像图片</el-button><el-button :disabled="picker.loading || picker.page * 20 >= picker.count" @click="picker.next">下一页头像图片</el-button><el-button @click="picker.close">返回配送员编辑</el-button></div></template></el-dialog>
  <el-dialog v-for="confirmation in confirmations" :key="confirmation.key" class="delivery-author-dialog" top="16px" :model-value="true" title="确认配送员操作" width="min(560px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><p>{{ operationLabels[confirmation.operation] }}<span v-if="confirmation.id"> #{{ confirmation.id }}</span></p><p v-if="confirmation.operation === 'create' || confirmation.operation === 'update'">{{ confirmation.payload.nickname }} · UID {{ confirmation.payload.uid }} · {{ confirmation.payload.phone }}</p><p v-if="confirmation.operation === 'status'">启用配送员需要关联商城用户仍然有效，且平台配送身份及手机号不重复。</p><p v-if="confirmation.operation === 'delete'">删除会将该平台配送员移入回收状态并停用。已有订单记录保留。</p><template #footer><el-button :disabled="state.busy" @click="confirmation.cancel">取消配送员操作</el-button><el-button type="primary" :disabled="state.busy" @click="confirmation.confirm">确认配送员提交</el-button></template></el-dialog>
 </main>
</template>

<script setup lang="ts">
import { computed, reactive, watch, onMounted, onBeforeUnmount } from 'vue';
import { useRoute } from 'vue-router';
import { useAuthStore } from '@/stores/auth';
import { getAdminSession, getToken } from '@/utils/auth';
import { apiDeliveryAuthorCatalog, apiDeliveryAuthorCommit, apiDeliveryAuthorReceipt, apiDeliveryAuthorResolve, apiDeliveryAuthorCategories, apiDeliveryAuthorOptions, apiDeliveryAuthorUsers } from '@/api/deliveryAuthor';
import { deliveryAuthorState } from '@/utils/deliveryAuthorState';
import { deliveryPreview, type DeliveryAction, type DeliveryOperation, type DeliveryValues } from '../../../../common/deliveryAuthor';

const props = defineProps<{ active: boolean }>();
const emit = defineEmits<{ changed: []; 'page-active-count': [count: number] }>();
const auth = useAuthStore(), route = useRoute();
let alive = false, generation = 0, syncing = false, queued = false;
const allowed = (values: string[]) => auth.uniqueAuth.some(p => p === '*' || p === 'order.*' || values.includes(p));
const canView = computed(() => props.active && !!auth.token && auth.token === getToken() && !!auth.userInfo && (auth.userInfo.level === 0 || allowed(['order.view', 'order.manage'])));
const canManage = computed(() => canView.value && (auth.userInfo?.level === 0 || allowed(['order.manage'])));
const prefix = (actor: number) => `cinashop_delivery_pending_v1_${actor}_`;
function keys(actor: number) { const result: string[] = []; for (let i = 0; i < localStorage.length; i++) { const key = localStorage.key(i); if (key?.startsWith(prefix(actor))) result.push(key); } return result.sort(); }
const model = deliveryAuthorState({ identity: () => `${generation}:${auth.token}:${auth.userInfo?.id}`, actor: () => auth.userInfo?.id ?? 0,
  view: () => canView.value, manage: () => canManage.value, read: apiDeliveryAuthorCatalog, write: apiDeliveryAuthorCommit, receipt: apiDeliveryAuthorReceipt, resolve: apiDeliveryAuthorResolve,
  categories: apiDeliveryAuthorCategories, options: apiDeliveryAuthorOptions, users: apiDeliveryAuthorUsers, changed: () => emit('changed'),
  readPending: actor => { const key = keys(actor)[0]; if (!key) return null; const raw = localStorage.getItem(key); if (!raw || raw.length > 512 * 1024) throw Error('原配送员操作记录异常，请保留核对'); const a = JSON.parse(raw); if (key !== prefix(actor) + a?.operation_id) throw Error('原配送员操作标识不一致'); return a; },
  persist: (actor: number, a: DeliveryAction | null, expected?: DeliveryAction) => {
    const value = a ?? expected; if (!value) throw Error('缺少原配送员操作'); const key = prefix(actor) + value.operation_id, raw = localStorage.getItem(key);
    if (a) { const text = JSON.stringify(a); if (text.length > 512 * 1024 || keys(actor).some(k => k !== key) || raw && raw !== text) throw Error('本账号已有其它未确认配送员操作'); localStorage.setItem(key, text); }
    else { if (raw && raw !== JSON.stringify(expected)) throw Error('原配送员操作记录已变化，无法清除'); localStorage.removeItem(key); }
  },
}, v => reactive(v) as typeof v);
const state = model.state;
const screens = computed(() => [model.screen()]), editors = computed(() => model.editorControls()), pickers = computed(() => model.pickerControls());
const userPickers = computed(() => model.userControls()), confirmations = computed(() => model.confirmationControls());
const visible = computed(() => model.visible()), pageCount = computed(() => model.pageCount());
const rows = computed(() => visible.value.slice((state.filters.page - 1) * 20, state.filters.page * 20).map(model.rowControls));
watch(() => rows.value.filter(item => item.row.status === 1).length, count => emit('page-active-count', count), { immediate: true });
const editorLocked = computed(() => !model.writable() || !!state.picker || !!state.users);
const labels: Record<keyof DeliveryValues, string> = { uid: '关联用户UID', avatar: '头像', nickname: '配送员名称', phone: '联系电话', status: '配送员状态' };
const operationLabels: Record<DeliveryOperation, string> = { create: '新增配送员', update: '保存配送员', status: '调整配送员状态', delete: '软删除配送员' };
function schedule() {
  if (!alive || syncing) return; generation++; model.dispose(); if (queued) return; queued = true;
  queueMicrotask(() => { queued = false; if (alive && props.active) void model.activate(); });
}
function syncStored(event?: Event) {
  if (syncing || event instanceof StorageEvent && event.key !== null && !['admin_token', 'admin_session'].includes(event.key) && !event.key.startsWith('cinashop_delivery_pending_v1_')) return;
  syncing = true; generation++; model.dispose(); const session = getAdminSession();
  auth.$patch({ token: getToken() ?? '', userInfo: session?.userInfo ?? null, menus: (session?.menus as typeof auth.menus) ?? [], uniqueAuth: session?.uniqueAuth ?? [] }); syncing = false; schedule();
}
watch(() => [auth.token, auth.userInfo, auth.uniqueAuth, auth.menus], schedule, { deep: true, flush: 'sync' });
watch(() => route.fullPath, schedule, { flush: 'sync' }); watch(() => props.active, schedule, { flush: 'sync' });
const stopAction = auth.$onAction(({ name, after }) => { if (name === 'login' || name === 'logout') after(schedule); });
onMounted(() => { alive = true; window.addEventListener('storage', syncStored); window.addEventListener('admin-session-changed', syncStored); window.addEventListener('admin-auth-expired', syncStored); syncStored(); });
onBeforeUnmount(() => { alive = false; generation++; stopAction(); model.dispose(); window.removeEventListener('storage', syncStored); window.removeEventListener('admin-session-changed', syncStored); window.removeEventListener('admin-auth-expired', syncStored); });
</script>
<style scoped>
.delivery-author,.delivery-author>section{display:grid;gap:16px;min-width:0}.heading,.actions,.identity{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.heading{justify-content:space-between}.heading h2{font-size:20px;margin:0}.heading p,.hint,.delivery-info p,small{color:var(--el-text-color-secondary);font-size:13px;line-height:1.7;margin:6px 0}.filters,.picker-filters{display:grid;grid-template-columns:minmax(180px,1fr) auto;gap:12px;align-items:end}.filters label,.editor-fields label,.picker-filters label,.region-fields label{display:grid;gap:8px;font-size:14px}.editor-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:12px}.editor-fields>fieldset,.editor-fields>label:has(textarea){grid-column:1/-1}input,select,textarea{box-sizing:border-box;max-width:100%;width:100%;min-width:0;border:1px solid var(--el-border-color);border-radius:4px;background:var(--el-bg-color);color:var(--el-text-color-primary);font:inherit;padding:9px 12px}input:focus,select:focus,textarea:focus{outline:2px solid var(--el-color-primary);outline-offset:1px}input:disabled,select:disabled,textarea:disabled{opacity:.6}fieldset{border:1px solid var(--el-border-color);border-radius:6px;padding:12px;min-width:0}legend{font-size:14px;padding:0 6px}.reference{font-size:12px;overflow-wrap:anywhere}.editor-avatar{width:140px;max-width:100%;height:100px;object-fit:contain}.delivery-thumbnail{width:72px;height:60px;object-fit:contain}.delivery-rows{border:1px solid var(--el-border-color);border-radius:6px}.delivery-row{display:flex;justify-content:space-between;gap:16px;padding:16px}.delivery-row+.delivery-row{border-top:1px solid var(--el-border-color-lighter)}.delivery-info{min-width:0;overflow-wrap:anywhere}.actions .el-button+.el-button{margin-left:0}.pagination{justify-content:flex-end;font-size:13px}.empty{padding:20px}.image-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:16px}.delivery-image-option{display:grid;gap:8px;min-width:0;padding:8px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color);cursor:pointer;overflow-wrap:anywhere}.delivery-image-option img{width:100%;height:80px;object-fit:contain}.delivery-image-option:focus{outline:2px solid var(--el-color-primary)}.time-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.region-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.location-frame{width:100%;height:clamp(240px,58dvh,520px);border:0;display:block}.delivery-author :deep(.el-overlay-dialog){overflow:clip}.delivery-author :deep(.delivery-author-dialog){max-height:calc(100dvh - 32px);display:flex;flex-direction:column}.delivery-author :deep(.delivery-author-dialog .el-dialog__body){min-height:0;overflow:auto}.delivery-author :deep(.delivery-author-dialog .el-dialog__header),.delivery-author :deep(.delivery-author-dialog .el-dialog__footer){flex-shrink:0}.delivery-author :deep(.el-alert__content){min-width:0;overflow-wrap:anywhere}@media(max-width:760px){.delivery-row{flex-direction:column}.filters{grid-template-columns:1fr 160px}.image-options{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:480px){.filters,.picker-filters,.editor-fields,.region-fields{grid-template-columns:1fr}.heading>.actions{width:100%}.delivery-row{padding:12px}.pagination{justify-content:flex-start}.time-fields{grid-template-columns:1fr}.image-options{grid-template-columns:repeat(2,minmax(0,1fr))}}
.user-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:16px}.delivery-user-option{display:flex;align-items:center;gap:12px;min-width:0;padding:12px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color);color:inherit;text-align:left;cursor:pointer;overflow-wrap:anywhere}.delivery-user-option img{width:48px;height:48px;object-fit:contain;flex-shrink:0}.delivery-user-option span{min-width:0}.editor-fields fieldset small{display:block;margin:8px 0}@media(max-width:480px){.user-options{grid-template-columns:1fr}}
</style>
